+/// Read a secret from the controlling terminal without echoing it. The
+/// launcher normally drives this module through the command bar, so a missing
+/// tty is a normal condition — we fall back to stdin (echoed) rather than
+/// failing the action.
+fn read_password(prompt: &str) -> String {
+    use std::io::{BufRead, Write};
+    eprint!("{prompt}");
+    let _ = std::io::stderr().flush();
+    if let Ok(tty) = std::fs::File::options().read(true).write(true).open("/dev/tty") {
+        let mut line = String::new();
+        if let Ok(echo_fd) = tty.try_clone() {
+            let _ = std::process::Command::new("stty").arg("-echo").stdin(std::process::Stdio::from(echo_fd)).status();
+        }
+        let read = std::io::BufReader::new(tty).read_line(&mut line).is_ok();
+        let _ = std::process::Command::new("stty").arg("echo").stdin(std::process::Stdio::null()).status();
+        let _ = writeln!(std::io::stderr());
+        if read {
+            return line.trim_end_matches('\n').to_string();
+        }
+    }
+    let mut buf = String::new();
+    if std::io::stdin().read_line(&mut buf).is_err() {
+        return String::new();
+    }
+    buf.trim_end_matches('\n').to_string()
+}
