/// Relative, site-local path: no scheme, no absolute root, no `..`, no
/// backslashes — the entry can only ever point at a file the publisher put
/// next to the registry, joined onto the configured base URL.
fn is_safe_relpath(v: &str) -> bool {
    !v.is_empty()
        && v.len() <= 256
        && !v.contains("://")
        && !v.contains('\\')
        && !v.starts_with('/')
        && !v.split('/').any(|p| p == "..")
}

/// Registry ABI name for the platform we are running on; `None` on desktop,
/// where the store is browse-only and `scripts/dev-setup.sh` owns installs.
pub fn current_abi() -> Option<&'static str> {
    match (std::env::consts::OS, std::env::consts::ARCH) {
        ("android", "aarch64") => Some("android-arm64"),
        ("android", "x86_64") => Some("android-x86_64"),
        _ => None,
    }
}

/// ELF `e_machine` of an ABI's binaries (little-endian u16 at offset 18).
pub fn abi_e_machine(abi: &str) -> Option<u16> {
    match abi {
        "android-arm64" => Some(183), // EM_AARCH64
        "android-x86_64" => Some(62), // EM_X86_64
        _ => None,
    }
}
