// Palette follows a current dark-product pattern: tinted slate surfaces,
// teal for focus/primary marks, one warm CTA per screen. Contrast pairs are
// checked >= 4.5:1 on their surfaces.
export global ThemePalette {
    // -- themed colors (runtime-swappable via themes/*.json) --
    in-out property <color> canvas-bg: #020617;
    in-out property <color> surface-primary: #0F172A;
    in-out property <color> surface-border: #1E293B;
    in-out property <color> text-primary: #E2E8F0;
    in-out property <color> text-secondary: #94A3B8;
    in-out property <color> accent-focus: #2DD4BF;
    in-out property <length> border-width: 0px;
    in-out property <length> corner-radius: 4px;
    in-out property <string> font-family: "Inter";

    // -- derived roles (computed from the themed colors above, so they
    //    follow runtime theme switching for free) --
    in-out property <color> surface-elevated: lighter(ThemePalette.surface-primary, 0.06);
    in-out property <color> surface-pressed: ThemePalette.surface-border;
    in-out property <color> surface-hover: alpha(ThemePalette.surface-border, 0.5);
    in-out property <color> scrim: #00000099;
    in-out property <color> accent-cta: #EA580C;
