    // -- type scale (px roles; font-family is the only runtime-themed bit) --
    in-out property <length> font-size-xs: 10px;   // rail labels
    in-out property <length> font-size-sm: 12px;   // buttons, captions, statuses
    in-out property <length> font-size-md: 15px;   // rows, body text
    in-out property <length> font-size-lg: 16px;   // command input
    in-out property <length> font-size-icon: 14px; // monogram glyphs (one icon size)
}

// 4/8dp spacing rhythm and the motion envelope (150-200ms micro-transitions).
