{"kind":"tool","id":"eRU1yI3wEhk","toolName":"str_replace","input":{"path":"crates/mandala-core/src/state.rs","replacements":[{"oldString":"/// Text listing for the All-Apps drawer / live search results. The Store is","newString":"const ALARM_USAGE: &str =
    "usage: alarm 18:30 text   |   alarm cancel 2   |   alarm   (list upcoming)";

/// `alarm` command surface: `HH:MM <text>` with an optional `@app-id` target
/// right before the text routes the alarm to that module, else it fires as a
/// home notice. `cancel N` removes the n-th upcoming; bare `alarm` lists.
fn parse_alarm_command(args: &str) -> Result<Action, &'static str> {
    let args = args.trim();
    if args.is_empty() {
        return Ok(Action::ListAlarms);
    }
    if let Some(n) = args
        .strip_prefix("cancel")
        .map(str::trim)
        .and_then(|n| n.parse::<usize>().ok())
    {
        return Ok(Action::CancelAlarm { index: n });
    }
    let Some((when, rest)) = args.split_once(char::is_whitespace) else {
        return Err(ALARM_USAGE);
    };
    if let Err((h, m)) = parse_hhmm(when) {
        let _ = (h, m);
        return Err(ALARM_USAGE);
    }
    let (target, text) = match rest.trim_start().strip_prefix('@') {
        Some(t) => match t.split_once(char::is_whitespace) {
            Some((id, text)) if !id.is_empty() => (Some(id.to_string()), text.trim().to_string()),
            _ => (None, rest.trim().to_string()),
        },
        None => (None, rest.trim().to_string()),
    };
    if text.is_empty() {
        return Err(ALARM_USAGE);
    }
    Ok(Action::ScheduleAlarm {
        when: when.to_string(),
        text,
        target,
    })
}

/// `HH:MM` with valid hour/minute ranges.
fn parse_hhmm(s: &str) -> std::result::Result<(u8, u8), (u8, u8)> {
    let bad = (0u8, 0u8);
    let (h, m) = s.split_once(':').ok_or(bad)?;
    let n = |t: &str| -> std::result::Result<(u8, bool), (u8, u8)> {
        let digits = t.len() == 2 && t.bytes().all(|c| c.is_ascii_digit());
        t.parse::<u8>().map(|v| (v, digits)).map_err(|_| bad)
    };
    let (hh, hd) = n(h)?;
    let (mm, md) = n(m)?;
    if !hd || !md || hh > 23 || mm > 59 {
        return Err(bad);
    }
    Ok((hh, mm))
}

