/// `HH:MM` -> epoch ms of the next occurrence in the device's local zone
/// (today if still ahead, else tomorrow). None when `when` is malformed.
fn due_ms_from(when: &str) -> Option<u64> {
    use chrono::{Datelike, Local, NaiveTime, TimeZone, Timelike};
    let (h, m) = when.split_once(':')?;
    let (h, m) = (h.parse::<u32>().ok()?, m.parse::<u32>().ok()?);
    if h > 23 || m > 59 { return None; }
    let now = Local::now();
    let naive_today = now.date_naive().and_hms_opt(h, m, 0)?;
    let mut ms = now.timezone().from_local_datetime(&naive_today).earliest()?.timestamp_millis() as u64;
    if ms <= now_ms() {
        ms = now.timezone().from_local_datetime(&(naive_today + chrono::Duration::days(1))).earliest()?.timestamp_millis() as u64;
    }
    Some(ms)
}

/// Local `HH:MM` text of an epoch-ms time (for the alarm list).
fn alarm_hhmm(due_ms: u64) -> String {
    use chrono::{Local, TimeZone};
    let secs = (due_ms / 1000) as i64;
    let nanos = ((due_ms % 1000) * 1_000_000) as u32;
    match Local.timestamp_opt(secs, nanos) {
        chrono::LocalResult::Single(t) => t.format("%H:%M").to_string(),
        _ => String::new(),
    }
}
```
